// actor/scripts/seed.ts — reset an actor to the Pier 9 08:00 seed and nothing else. Usage: bun scripts/seed.ts [actorId] [speed]
import { PIER9 } from "../../shared/pier9"
import { ACTOR_ID, hhmm } from "../../shared/types"
// @ts-ignore generated by `terse actor generate`
import { actors } from "../generated/index.js"

const actorId = process.argv[2] ?? ACTOR_ID
const speed = Number(process.argv[3] ?? PIER9.speed ?? 60)
const s = await actors.Dock.get(actorId).seed({ ...PIER9, speed })
console.log(`${actorId} seeded: ${hhmm(s.simMin)} at ${s.speed}x, ${s.appts.length} appointments, next alarm ${s.timers[0] ? hhmm(s.timers[0].atMin) + " " + s.timers[0].kind : "none"}`)
